}

function readUint32BE(source, offset) {
  return (
    ((source[offset] << 24) |
      (source[offset + 1] << 16) |
      (source[offset + 2] << 8) |
      source[offset + 3]) >>>
    0
  );
}

function writeUint32BE(target, offset, value) {
  target[offset] = (value >>> 24) & 0xff;
  target[offset + 1] = (value >>> 16) & 0xff;
  target[offset + 2] = (value >>> 8) & 0xff;
  target[offset + 3] = value & 0xff;
}

export function sha1(messageBytes) {
  const totalLength = Math.ceil((messageBytes.length + 9) / SHA1_BLOCK_SIZE) * SHA1_BLOCK_SIZE;
  const padded = new Uint8Array(totalLength);
  const schedule = new Uint32Array(80);

  padded.set(messageBytes);
  padded[messageBytes.length] = 0x80;

  const bitLength = messageBytes.length * 8;
  const highBits = Math.floor(bitLength / 0x100000000);
  const lowBits = bitLength >>> 0;

  writeUint32BE(padded, totalLength - 8, highBits);
  writeUint32BE(padded, totalLength - 4, lowBits);

  let h0 = 0x67452301;
  let h1 = 0xefcdab89;
  let h2 = 0x98badcfe;
  let h3 = 0x10325476;
  let h4 = 0xc3d2e1f0;

  for (let chunkOffset = 0; chunkOffset < padded.length; chunkOffset += SHA1_BLOCK_SIZE) {
    for (let index = 0; index < 16; index += 1) {
      schedule[index] = readUint32BE(padded, chunkOffset + index * 4);
    }

    for (let index = 16; index < 80; index += 1) {
      schedule[index] = leftRotate(
        schedule[index - 3] ^ schedule[index - 8] ^ schedule[index - 14] ^ schedule[index - 16],
        1,
      );
    }

    let a = h0;
    let b = h1;
    let c = h2;
    let d = h3;
    let e = h4;

    for (let index = 0; index < 80; index += 1) {
      let f;
      let k;

      if (index < 20) {
        f = (b & c) | (~b & d);
        k = 0x5a827999;
      } else if (index < 40) {
        f = b ^ c ^ d;
        k = 0x6ed9eba1;
      } else if (index < 60) {
        f = (b & c) | (b & d) | (c & d);
        k = 0x8f1bbcdc;
      } else {
        f = b ^ c ^ d;
        k = 0xca62c1d6;
      }

      const next = (leftRotate(a, 5) + f + e + k + schedule[index]) >>> 0;

      e = d;
      d = c;
      c = leftRotate(b, 30);
      b = a;
      a = next;
    }

    h0 = (h0 + a) >>> 0;
    h1 = (h1 + b) >>> 0;
    h2 = (h2 + c) >>> 0;
    h3 = (h3 + d) >>> 0;
    h4 = (h4 + e) >>> 0;
