import {
  ArgumentParseError,
  HelpRequested,
  formatError,
  getProgramName,
  parseArgs,
} from './lib/cli.mjs';
import { bytesToHex } from './lib/encoding.mjs';
import { PBKDF2 } from './lib/pbkdf2.mjs';

function main(argv = process.argv.slice(2), scriptPath = process.argv[1]) {
  const programName = getProgramName(scriptPath);

  try {
    const args = parseArgs(argv, programName);
    const result = new PBKDF2(args.a, args.b, args.c).read(20);
    process.stdout.write(`${bytesToHex(result)}\n`);
  } catch (error) {
    if (error instanceof HelpRequested) {
      process.stdout.write(error.helpText);
      return 0;
    }

    if (error instanceof ArgumentParseError) {
      process.stderr.write(formatError(programName, error.message));
      return 2;
    }

    throw error;
  }

  return 0;
}

