import { sha1, SHA1_BLOCK_SIZE, SHA1_DIGEST_SIZE } from './sha1.mjs';

export const HMAC_SHA1_DIGEST_SIZE = SHA1_DIGEST_SIZE;

export function hmacSha1(keyBytes, messageBytes) {
  let normalizedKey = keyBytes;

  if (normalizedKey.length > SHA1_BLOCK_SIZE) {
    normalizedKey = sha1(normalizedKey);
  }

  const inner = new Uint8Array(SHA1_BLOCK_SIZE + messageBytes.length);
  const outer = new Uint8Array(SHA1_BLOCK_SIZE + SHA1_DIGEST_SIZE);

  inner.fill(0x36, 0, SHA1_BLOCK_SIZE);
  outer.fill(0x5c, 0, SHA1_BLOCK_SIZE);

  for (let index = 0; index < normalizedKey.length; index += 1) {
    inner[index] ^= normalizedKey[index];
    outer[index] ^= normalizedKey[index];
  }

  inner.set(messageBytes, SHA1_BLOCK_SIZE);
  outer.set(sha1(inner), SHA1_BLOCK_SIZE);

  return sha1(outer);
}

