const NEGATIVE_NUMBER_RE = /^-\d+$|^-\d*\.\d+$/;
const INTEGER_RE = /^[+-]?(?:\d(?:_?\d)*)$/;

export class HelpRequested extends Error {
  constructor(helpText) {
    super('help requested');
    this.name = 'HelpRequested';
    this.helpText = helpText;
  }
}

export class ArgumentParseError extends Error {
  constructor(message) {
    super(message);
    this.name = 'ArgumentParseError';
  }
}

export function getProgramName(scriptPath) {
  if (!scriptPath) {
    return 'test2.mjs';
  }

  const normalized = String(scriptPath).replace(/\\/g, '/');
  const parts = normalized.split('/');
  return parts[parts.length - 1] || 'test2.mjs';
}

export function formatUsage(programName) {
  return `usage: ${programName} [-h] --a A --b B --c C`;
}

export function formatHelp(programName) {
  return `${formatUsage(programName)}\n\noptions:\n  -h, --help  show this help message and exit\n  --a A\n  --b B\n  --c C\n`;
}

export function formatError(programName, message) {
  return `${formatUsage(programName)}\n${programName}: error: ${message}\n`;
}

function isOptionalLike(token) {
  if (token == null || token === '' || token === '-') {
    return false;
  }

  if (!token.startsWith('-')) {
    return false;
  }

  if (token === '--') {
    return true;
  }

  return !NEGATIVE_NUMBER_RE.test(token);
}

function parseInteger(token) {
  if (!INTEGER_RE.test(token)) {
    return null;
  }

  const value = Number(token.replace(/_/g, ''));
  return Number.isInteger(value) ? value : null;
}

function readOptionValue(argv, index, optionName) {
  const value = argv[index + 1];

  if (value == null || isOptionalLike(value)) {
    throw new ArgumentParseError(`argument ${optionName}: expected one argument`);
  }

  return value;
}

export function parseArgs(argv, programName) {
  const result = { a: undefined, b: undefined, c: undefined };
  const unknownArguments = [];

  for (let index = 0; index < argv.length; index += 1) {
    const token = argv[index];

    if (token === '-h' || token === '--help') {
      throw new HelpRequested(formatHelp(programName));
    }

    if (token === '--') {
      for (let restIndex = index + 1; restIndex < argv.length; restIndex += 1) {
        unknownArguments.push(argv[restIndex]);
      }
      break;
    }

    if (token === '--a') {
      result.a = readOptionValue(argv, index, '--a');
      index += 1;
      continue;
    }

    if (token.startsWith('--a=')) {
      result.a = token.slice(4);
      continue;
    }

    if (token === '--b') {
      result.b = readOptionValue(argv, index, '--b');
      index += 1;
      continue;
    }

    if (token.startsWith('--b=')) {
      result.b = token.slice(4);
      continue;
    }

    if (token === '--c') {
      const rawValue = readOptionValue(argv, index, '--c');
      const parsedValue = parseInteger(rawValue);

      if (parsedValue == null) {
        throw new ArgumentParseError(`argument --c: invalid int value: '${rawValue}'`);
      }

      result.c = parsedValue;
      index += 1;
      continue;
    }

    if (token.startsWith('--c=')) {
      const rawValue = token.slice(4);
      const parsedValue = parseInteger(rawValue);

      if (parsedValue == null) {
        throw new ArgumentParseError(`argument --c: invalid int value: '${rawValue}'`);
      }

      result.c = parsedValue;
      continue;
    }

    unknownArguments.push(token);
  }

  const missingArguments = [];

  if (result.a === undefined) {
    missingArguments.push('--a');
  }

  if (result.b === undefined) {
    missingArguments.push('--b');
  }

  if (result.c === undefined) {
    missingArguments.push('--c');
  }

  if (missingArguments.length > 0) {
    throw new ArgumentParseError(
      `the following arguments are required: ${missingArguments.join(', ')}`,
    );
  }

  if (unknownArguments.length > 0) {
    throw new ArgumentParseError(`unrecognized arguments: ${unknownArguments.join(' ')}`);
  }

  return result;
}

