import { utf8ToBytes, writeUint32BE, xorInto } from './encoding.mjs';
import { hmacSha1, HMAC_SHA1_DIGEST_SIZE } from './hmac.mjs';

export const PBKDF2_DIGEST_SIZE = HMAC_SHA1_DIGEST_SIZE;

export class ValueError extends Error {
  constructor(message) {
    super(message);
    this.name = 'ValueError';
  }
}

function normalizeInput(value) {
  return value instanceof Uint8Array ? value : utf8ToBytes(value);
}

export class PBKDF2 {
  constructor(passphrase, salt, iterations = 1000) {
    if (!Number.isInteger(iterations)) {
      throw new TypeError('iterations must be an integer');
    }

    if (iterations < 1) {
      throw new ValueError('iterations must be at least 1');
    }

    this.passphraseBytes = normalizeInput(passphrase);
    this.saltBytes = normalizeInput(salt);
    this.iterations = iterations;
    this.blockIndex = 1;
    this.buffer = new Uint8Array(0);
    this.bufferOffset = 0;
  }

  read(byteCount) {
    if (!Number.isInteger(byteCount) || byteCount < 0) {
      throw new RangeError('byteCount must be a non-negative integer');
    }

    const output = new Uint8Array(byteCount);
    let written = 0;

    while (written < byteCount) {
      if (this.bufferOffset >= this.buffer.length) {
        this.buffer = this.deriveBlock(this.blockIndex);
        this.blockIndex += 1;
        this.bufferOffset = 0;
      }

      const available = this.buffer.length - this.bufferOffset;
      const remaining = byteCount - written;
      const chunkLength = available < remaining ? available : remaining;

      output.set(this.buffer.subarray(this.bufferOffset, this.bufferOffset + chunkLength), written);

      this.bufferOffset += chunkLength;
      written += chunkLength;
    }

    return output;
  }

  deriveBlock(blockIndex) {
    const blockInput = new Uint8Array(this.saltBytes.length + 4);
    blockInput.set(this.saltBytes);
    writeUint32BE(blockInput, this.saltBytes.length, blockIndex >>> 0);

    let u = hmacSha1(this.passphraseBytes, blockInput);
    const accumulator = new Uint8Array(u);

    for (let iteration = 1; iteration < this.iterations; iteration += 1) {
      u = hmacSha1(this.passphraseBytes, u);
      xorInto(accumulator, u);
    }

    return accumulator;
  }
}

export function pbkdf2Read(passphrase, salt, iterations, byteCount) {
  return new PBKDF2(passphrase, salt, iterations).read(byteCount);
}

