export const SHA1_BLOCK_SIZE = 64;
export const SHA1_DIGEST_SIZE = 20;

function leftRotate(value, shift) {
  return ((value << shift) | (value >>> (32 - shift))) >>> 0;
}

function readUint32BE(source, offset) {
  return (
    ((source[offset] << 24) |
      (source[offset + 1] << 16) |
      (source[offset + 2] << 8) |
      source[offset + 3]) >>>
    0
  );
}

