function usageLine(programName) {
  return `usage: ${programName} [-h] --a A --b B --c C`;
}

function helpText(programName) {
  return `${usageLine(programName)}\n\noptions:\n  -h, --help  show this help message and exit\n  --a A\n  --b B\n  --c C\n`;
}

function parseIntArgument(rawValue) {
  if (!/^[+-]?\d+$/.test(rawValue)) {
    return null;
  }

  return Number(rawValue);
}

function isNegativeNumberLike(token) {
  return /^-\d+$/.test(token) || /^-\d*\.\d+$/.test(token);
}

function isOptionLike(token) {
  return token.startsWith('-') && !isNegativeNumberLike(token);
}

function splitInlineValue(token) {
  const equalsIndex = token.indexOf('=');

  if (equalsIndex === -1) {
    return { name: token, hasInlineValue: false, inlineValue: '' };
  }

  return {
    name: token.slice(0, equalsIndex),
    hasInlineValue: true,
    inlineValue: token.slice(equalsIndex + 1),
  };
}

function formatMissingRequired(missingOptions) {
  return `the following arguments are required: ${missingOptions.join(', ')}`;
}

function formatError(programName, message) {
