    fail(programName, `argument -h/--help: ignored explicit argument '${token.slice(7)}'`);
  }

  if (token.startsWith('-h=')) {
    fail(programName, `argument -h/--help: ignored explicit argument '${token.slice(3)}'`);
  }

  if (token === '-h' || token === '--help' || (token.startsWith('-h') && !token.startsWith('--'))) {
