import { concatBytes, int32ToBigEndianBytes, xorInto } from '../bytes.mjs';
import { hmacSha1 } from './hmac_sha1.mjs';

const SHA1_DIGEST_LENGTH = 20;

export function pbkdf2HmacSha1(passwordBytes, saltBytes, iterations, keyLength) {
  if (!Number.isInteger(iterations) || iterations < 1) {
    throw new Error('iterations must be at least 1');
  }

  if (!Number.isInteger(keyLength) || keyLength < 0) {
    throw new Error('key length must be at least 0');
  }

  const blockCount = Math.ceil(keyLength / SHA1_DIGEST_LENGTH);
  const derivedKey = new Uint8Array(keyLength);

  for (let blockIndex = 1; blockIndex <= blockCount; blockIndex += 1) {
    let block = hmacSha1(
      passwordBytes,
      concatBytes(saltBytes, int32ToBigEndianBytes(blockIndex)),
    );
    const accumulator = new Uint8Array(block);

    for (let round = 1; round < iterations; round += 1) {
      block = hmacSha1(passwordBytes, block);
      xorInto(accumulator, block);
    }

    const writeOffset = (blockIndex - 1) * SHA1_DIGEST_LENGTH;
    const remaining = keyLength - writeOffset;
    derivedKey.set(
      accumulator.subarray(0, Math.min(SHA1_DIGEST_LENGTH, remaining)),
      writeOffset,
    );
  }

  return derivedKey;
}

