import { toHex } from './bytes.mjs';
import { pbkdf2HmacSha1 } from './crypto/pbkdf2_sha1.mjs';
import { encodeUtf8 } from './text/utf8.mjs';

export function deriveKeyHex(passphrase, salt, iterations, keyLength = 20) {
  const passwordBytes = encodeUtf8(passphrase);
  const saltBytes = encodeUtf8(salt);
  const derivedKey = pbkdf2HmacSha1(
    passwordBytes,
    saltBytes,
    iterations,
    keyLength,
  );

  return toHex(derivedKey);
}

